INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(1,'Proxy DNS Records through Cloudflare','Ensure all relevant DNS records (A, AAAA, CNAME) pointing to your origin are proxied (orange-clouded) through Cloudflare to hide origin IPs and apply security and performance features.','General',1,1,'Mandatory','High','Easy','Cloudflare must manage the DNS records',NULL,'https://developers.cloudflare.com/dns/proxy-status/','Proxying is required for Cloudflare application services (WAF, rate limiting, bot protection, caching) to apply. Avoid DNS-only (grey-clouded) records unless needed for non-HTTP use cases: they expose the origin IP address.','2025-04-22 08:24:32','2026-10-03 23:29:12');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(2,'Enable DNSSEC','Enable Domain Name System Security Extensions to ensure DNS responses are authentic.','Security',1,1,'Recommended','High','Easy','It is recommended to have Cloudflare be the Authoritative DNS provider',NULL,'https://developers.cloudflare.com/dns/dnssec/','Assumes Cloudflare is the authoritative DNS provider.','2025-04-22 08:24:32','2025-04-22 08:24:32');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(3,'Test Rules with "Log" Action','Before applying blocking actions (Block, Managed Challenge, etc.), test WAF or Rate Limiting rules using the "Log" action to observe matches in Security Events.','General',4,2,'Recommended','Medium','Easy',NULL,NULL,'https://developers.cloudflare.com/ruleset-engine/rules-language/actions/','Log action allows you to see what would be blocked without actually blocking it.','2025-04-22 08:24:32','2025-04-22 08:24:32');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(4,'Deploy WAF Managed Ruleset','Enable the core Cloudflare Managed Ruleset for baseline protection against common web threats.','Security',3,2,'Recommended','High','Easy','None',NULL,'https://developers.cloudflare.com/waf/managed-rules/','Deploy globally and create exceptions if needed. If you have multiple domains, configure the Account-level WAF.','2025-04-22 08:24:32','2025-04-22 08:24:32');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(5,'Enable Stricter WAF Rule: XSS','Enable the specific WAF Managed Rule for XSS, HTML Injection.','Security',3,2,'Situational','Medium','Easy','Proxied DNS Records','Enable Rule ID: 882b37d6bd5f4bf2a3cdb374d503ded0','https://developers.cloudflare.com/waf/managed-rules/reference/cloudflare-managed-ruleset/',NULL,'2025-04-22 08:24:32','2025-04-22 08:24:32');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(6,'Enable Stricter WAF Rule: Path Anomalies','Enable the WAF Managed Rule for URL Path Anomalies (Multiple Slashes, Relative Paths, CR, LF, NULL).','Security',3,2,'Situational','Medium','Easy','Proxied DNS Records','Enable Rule ID: 6e759e70dc814d90a003f10424644cfb','https://developers.cloudflare.com/waf/managed-rules/reference/cloudflare-managed-ruleset/',NULL,'2025-04-22 08:24:32','2025-04-22 08:24:32');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(7,'Enable Stricter WAF Rule: Large Body','Enable the WAF Managed Rule for anomalously large request bodies.','Security',3,2,'Situational','Medium','Easy','Proxied DNS Records','Enable Rule ID: 7b822fd1f5814e17888ded658480ea8f','https://developers.cloudflare.com/waf/managed-rules/reference/cloudflare-managed-ruleset/','Mitigates body payloads > processing limit. Add exceptions for your upload endpoints.','2025-04-22 08:24:32','2025-04-22 08:24:32');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(8,'Enable Stricter WAF Rule: Non Standard Port','Enable the WAF Managed Rule to block requests targeting non-standard HTTP/S ports (not 80 or 443).','Security',3,2,'Situational','Medium','Easy','Proxied DNS Records','Enable Rule ID: 8e361ee4328f4a3caf6caf3e664ed6fe','https://developers.cloudflare.com/waf/managed-rules/reference/cloudflare-managed-ruleset/','Blocks requests to non-standard ports (e.g., 8080, 8443). Alternatively, one can use a Custom Rule with the "cf.edge.server_port" field.','2025-04-22 08:24:32','2025-04-22 08:24:32');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(9,'Enable Stricter WAF Rule: Unusual/Unknown HTTP Method','Enable WAF Managed Rules for unusual or unknown HTTP Methods.','Security',3,2,'Situational','Medium','Easy','Proxied DNS Records','Enable Rule IDs: ab53f93c9b03472ab34a5405d9bdc7d5, 6e2240ffcb87477bbd4881b6fd13142f','https://developers.cloudflare.com/waf/managed-rules/reference/cloudflare-managed-ruleset/',NULL,'2025-04-22 08:24:32','2025-04-22 08:24:32');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(10,'Enable Stricter WAF Rule: Vulnerability Scanners','Enable all WAF Managed Rules related to vulnerability scanner activity.','Security',3,2,'Situational','Medium','Easy','Proxied DNS Records','Refer to WAF Managed Ruleset documentation for specific Rule IDs.','https://developers.cloudflare.com/waf/managed-rules/reference/cloudflare-managed-ruleset/',NULL,'2025-04-22 08:24:32','2025-04-22 08:24:32');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(11,'Log Matched Rule Payload','If needed for diagnostics, enable payload logging for matched WAF rules.','Security',3,2,'Optional','Medium','Easy','Proxied DNS Records','Configure via WAF Managed Rules settings.','https://developers.cloudflare.com/waf/managed-rules/payload-logging/','Log encrypted payloads in Firewall event logs metadata.','2025-04-22 08:24:32','2025-04-22 08:24:32');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(12,'Disable Browser Integrity Check (BIC)','Consider disabling BIC via Configuration Rules, specifically to prevent potential false positives with APIs or automated traffic.','Security',3,2,'Recommended','Medium','Easy','Proxied DNS Records','Disable in the Zone Security Settings.','https://developers.cloudflare.com/waf/tools/browser-integrity-check/',NULL,'2025-04-22 08:24:32','2025-04-22 08:24:32');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(13,'Deploy OWASP Core Ruleset','If required, review and deploy the OWASP Core Ruleset. Adapt to your needs.','Security',3,2,'Situational','High','Easy','Proxied DNS Records','Enable via the Zone Security Settings.','https://developers.cloudflare.com/waf/managed-rules/reference/owasp-core-ruleset/','OWASP Rulesets are prone to false positives. Add exceptions for Zaraz endpoint if used and any other sensitive path. Recommended setup: Paranoia Level is set to PL1, OWASP Score 60 and higher and Managed Challenge default action.','2025-04-22 08:24:32','2025-04-22 08:24:32');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(14,'Allow Verified Bots (WAF Skip)','Create a WAF Custom Rule with a SKIP action to explicitly allow known good bots like search engine crawlers.','Security',4,2,'Recommended','Medium','Medium',NULL,'(cf.verified_bot_category in {"Search Engine Crawler" "Search Engine Optimization" "Monitoring & Analytics" "Academic Research" "Security" "Accessibility" "Webhooks" "Feed Fetcher" "Archiver"})','https://developers.cloudflare.com/bots/concepts/bot/verified-bots/','Place this rule first. AI crawlers are verified bots too, so skip only the verified bot categories you rely on and manage AI crawlers with AI Crawl Control. cf.verified_bot_category is available on all plans. You might also want to allow sitemap.xml, robots.txt, or RSS feeds to everyone.','2025-04-22 08:24:32','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(15,'Allow Specific APIs (WAF Skip)','Create a WAF Custom Rule with a SKIP action to allow trusted API traffic (own or partner APIs), using specific match criteria (hostname, path, method, headers, etc.).','Security',4,2,'Recommended','Medium','Medium',NULL,'(http.host eq "api.example.com" and starts_with(http.request.uri.path, "/api/resources") and http.request.method eq "GET" and cf.waf.score gt 70 and cf.bot_management.score lt 10 and any(http.request.headers["x-api-shield"][*] eq "DEMO"))','https://developers.cloudflare.com/waf/custom-rules/skip/','Be as specific as possible and never embed secrets (API keys, tokens) in rule expressions. The ultimate goal should be a positive security model with API Shield (Schema Validation, JWT Validation).','2025-04-22 08:24:32','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(16,'Redirect Specific Traffic via Custom HTML','Use a WAF Custom Rule with Block action and Custom HTML response type to redirect certain requests (e.g., non-verified bots from a specific country).','Security',4,2,'Situational','Low','Medium',NULL,'`(ip.src.country eq "US" and not cf.bot_management.verified_bot)`. Action: Block, Response Type: Custom HTML, Response Code: 418, Body: `<meta http-equiv=refresh content=''0; URL=http://example.com/''>`','https://developers.cloudflare.com/waf/custom-rules/create-dashboard/#configure-a-custom-response-for-blocked-requests','You can customize the response for blocked requests, even inserting your own brand.','2025-04-22 08:24:32','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(17,'Block Fallthrough API Requests (API Shield)','If using API Shield with a positive security model, create a WAF rule to block requests to API hostnames that do not match any saved and defined operation/endpoint.','Security',9,6,'Recommended','High','Easy',NULL,'(http.host in {"api.example.com"} and cf.api_gateway.fallthrough_detected)','https://developers.cloudflare.com/ruleset-engine/rules-language/fields/reference/cf.api_gateway.fallthrough_detected/','Enforces positive security model. Requires a Cloudflare API Shield subscription.','2025-04-22 08:24:32','2026-10-03 23:29:12');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(18,'Log Non-Standard HTTP Methods','Create a WAF Custom Rule with Log action to gain visibility into non-standard HTTP methods being used (POST, PUT, DELETE etc.) on specific endpoints.','Security',4,2,'Situational','Low','Easy',NULL,'(http.request.method in {"POST" "PURGE" "PUT" "HEAD" "OPTIONS" "DELETE" "PATCH"})','https://developers.cloudflare.com/ruleset-engine/rules-language/fields/reference/http.request.method/',NULL,'2025-04-22 08:24:32','2026-10-03 23:29:12');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(19,'Mitigate Likely Malicious Requests (WAF Attack Score)','Create a WAF Custom Rule to challenge or block requests with a low WAF Attack Score (indicating likely SQLi, XSS, RCE).','Security',4,2,'Recommended','Medium','Easy',NULL,'(cf.waf.score lt 20)','https://developers.cloudflare.com/waf/custom-rules/use-cases/block-attack-score/','Start with Log, review Security Events, then use Managed Challenge or Block. Cloudflare''s own adaptive AI testing (Birthday Week 2026) ran Attack Score blocking scores of 30 or below. Business plans can use cf.waf.score.class (for example, "attack"); per Birthday Week 2026, Attack Score is being made available to all customers.','2025-04-22 08:24:32','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(20,'Mitigate Traffic from Managed IP Lists','Create WAF Custom Rules to block or challenge traffic based on Cloudflare Managed IP Lists (Anonymizers, Botnets, Malware, Open Proxies, VPNs).','Security',4,14,'Recommended','High','Easy',NULL,'(ip.src in $cf.botnets_command_and_control) or (ip.src in $cf.malware)','https://developers.cloudflare.com/waf/tools/lists/managed-lists/','Typically block Botnets/Malware. Consider mitigating specific VPN ASNs manually if needed.','2025-04-22 08:24:32','2026-10-03 23:29:12');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(21,'Mitigate Tor Traffic (WAF Rule)','Create a WAF Custom Rule to block or challenge traffic originating from the Tor network if it is unwanted.','Security',4,2,'Situational','Medium','Easy',NULL,'(ip.src.continent eq "T1")','https://developers.cloudflare.com/ruleset-engine/rules-language/fields/reference/ip.src.continent/','Ensure Onion Routing feature is disabled in the Zone Network Settings if blocking Tor.','2025-04-22 08:24:32','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(22,'Mitigate Unwanted (ASNs) Networks','Create WAF Custom Rules (preferably using Lists) to block or challenge traffic from specific Autonomous System Numbers (ASNs), such as unwanted cloud providers / infrastructure or specific networks.','Security',4,2,'Situational','High','Easy','','(ip.src.asnum in {24940 63949 20473 197540 15169 14061 16276 61317 16509 8075 60781 4134 51167 21069 7552 4766 45899 31898 6939 4837 14618 136787 7311})','https://developers.cloudflare.com/ruleset-engine/rules-language/fields/reference/ip.src.asnum/','Use Lists for easier management.','2025-04-22 08:24:32','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(23,'Block High Risk Countries (OFAC)','Create a WAF Custom Rule to block traffic from countries identified as high-risk or subject to sanctions (e.g., OFAC list).','Security',4,2,'Situational','Medium','Easy',NULL,'(ip.src.country in {"AF" "BY" "CF" "CG" "CD" "CI" "CU" "ET" "IR" "IQ" "KP" "LR" "ML" "MM" "SO" "SS" "SD" "SY" "VE" "YE" "ZW" "ER"})','https://sanctionssearch.ofac.treas.gov/','The List requires updating based on current sanctions lists. Use the Cloudflare API, SDK, or Terraform for automation.','2025-04-22 08:24:32','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(24,'Block Known Bot User-Agents','Create a WAF Custom Rule to block requests with User-Agent strings commonly used by unwanted bots (e.g., curl, go-http-client, empty).','Security',4,2,'Situational','Low','Easy',NULL,'(lower(http.user_agent) contains "python" or lower(http.user_agent) contains "go-http-client" or lower(http.user_agent) contains "scrapy" or lower(http.user_agent) contains "libwww-perl" or lower(http.user_agent) contains "fasthttp" or lower(http.user_agent) contains "undici" or lower(http.user_agent) contains "curl" or lower(http.user_agent) contains "wget" or http.user_agent eq "")','https://developers.cloudflare.com/ruleset-engine/rules-language/fields/reference/http.user_agent/','Be careful with over-blocking some User-Agents.','2025-04-22 08:24:32','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(25,'Restrict WordPress (WP) Admin Access (IP/Access)','For WordPress (WP) sites, restrict (block) access to /wp-admin using a WAF Custom Rule matching specific source IPs (preferably via List) or (highly recommended) implement Zero Trust using Cloudflare Access.','Security',10,2,'Recommended','High','Easy',NULL,'((starts_with(http.request.uri.path, "/wp-admin") or http.request.uri.path eq "/wp-login.php") and not http.request.uri.path eq "/wp-admin/admin-ajax.php" and not ip.src in $allowed_ips)','https://developers.cloudflare.com/waf/tools/lists/','Preferably use Cloudflare Access for a Zero Trust approach instead.','2025-04-22 08:24:32','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(26,'Restrict Access to Employee Locations (IP/Access)','For internal portals, restrict (block) access using a WAF Custom Rule to only allow countries where employees are located, or preferably (and highly recommended) use Cloudflare Access.','Security',10,2,'Recommended','Medium','Easy',NULL,'(not ip.src.country in {"US" "GB"})','https://developers.cloudflare.com/waf/custom-rules/use-cases/allow-traffic-from-specific-countries/','Be specific with your rules. Consider mTLS as an alternative, however, it is strongly recommended to use Cloudflare Access instead.','2025-04-22 08:24:32','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(27,'Enforce mTLS Authentication','For specific hostnames requiring mutual TLS, create a WAF Custom Rule to block requests without a valid, verified client certificate.','Security',10,10,'Recommended','High','Easy',NULL,'(http.host in {"mtls.example.com" "mtls2.example.com"} and (not cf.tls_client_auth.cert_verified or cf.tls_client_auth.cert_revoked))','https://developers.cloudflare.com/learning-paths/mtls/mtls-app-security/related-features/#waf-for-client-certificates','Follow the best practices for mTLS configuration. Ensure the client certificate is verified and not expired.','2025-04-22 08:24:32','2026-10-03 23:29:12');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(28,'Block Revoked mTLS Certificates','Enhance mTLS by also blocking requests presenting a revoked client certificate.','Security',10,10,'Recommended','High','Easy',NULL,'(http.host in {"mtls.example.com"} and (not cf.tls_client_auth.cert_verified or cf.tls_client_auth.cert_revoked))','https://developers.cloudflare.com/learning-paths/mtls/mtls-app-security/related-features/#certificate-revocation','Follow the best practices for mTLS configuration. Ensure the client certificate is verified and not expired.','2025-04-22 08:24:32','2026-10-03 23:29:12');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(29,'Allow Specific mTLS Client Certificates','For granular control, create WAF rules to allow mTLS access only for specific client certificate serial numbers or even the issuer Subject Key Identifier (SKI) hash on certain hostnames.','Security',10,10,'Situational','Medium','Easy',NULL,'(http.host in {"mtls.example.com"} and cf.tls_client_auth.cert_serial ne "SPECIFIC_SERIAL_NUMBER")','https://developers.cloudflare.com/api-shield/security/mtls/configure/#create-an-mtls-rule','Review the available mTLS fields for Rules.','2025-04-22 08:24:32','2026-10-03 23:29:12');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(30,'Challenge Admin JWT Users with High WAF Score','For APIs using JWT, create a WAF Custom Rule to challenge or block requests where the JWT indicates an admin user AND the WAF Attack Score is high.','Security',9,2,'Situational','Medium','Easy',NULL,'(lookup_json_string(http.request.jwt.claims["<TOKEN_CONFIGURATION_ID>"][0], "user") eq "admin" and cf.waf.score lt 40)','https://developers.cloudflare.com/waf/custom-rules/use-cases/check-jwt-claim-to-protect-admin-user/','Requires parsing JWT claims and using the Cloudflare API Shield JSON Web Tokens (JWT) Validation feature.','2025-04-22 08:24:32','2026-10-03 23:29:12');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(31,'Log Likely Automated Traffic (Bot Score)','Create a WAF Custom Rule with Log action to gain visibility into traffic Cloudflare classifies as likely automated based on Bot Score.','Security',6,4,'Recommended','Low','Easy',NULL,'(cf.bot_management.score lt 30 and not cf.bot_management.verified_bot and not cf.bot_management.static_resource)','https://developers.cloudflare.com/waf/custom-rules/use-cases/challenge-bad-bots/','Adjust threshold as needed. Requires a Cloudflare Enterprise Bot Management subscription.','2025-04-22 08:24:32','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(32,'Enforce JavaScript Detections (JSD)','For critical HTML sites, enforce JSD by challenging or blocking requests that fail the JSD check.','Security',6,4,'Situational','High','Easy','Requires a Cloudflare Enterprise Bot Management subscription.','(http.request.uri.path eq "/critical/path" and not cf.bot_management.js_detection.passed and not cf.bot_management.verified_bot and not cf.bot_management.static_resource)','https://developers.cloudflare.com/cloudflare-challenges/challenge-types/javascript-detections/#enforcing-execution-of-javascript-detections','Requires a Cloudflare Enterprise Bot Management subscription. JSD only injects on HTML responses and cannot run on the first HTML request.','2025-04-22 08:24:32','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(33,'Mitigate IPv6 Traffic (If Unwanted)','If IPv6 is not needed or desired, create a WAF Custom Rule to block or challenge traffic from IPv6 source addresses.','Security',4,2,'Situational','Low','Easy',NULL,'(ip.src in {::/0})','https://developers.cloudflare.com/network/ipv6-compatibility/','Consider disabling IPv6 compatibility in Zone Network Settings as well.','2025-04-22 08:24:32','2026-10-03 23:29:12');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(34,'Use Account Takeover (ATO) Detections','Leverage Cloudflare Enterprise Bot Management Detection IDs in WAF or Rate Limiting rules to mitigate predictable bot behavior like login failures.','Security',6,4,'Recommended','High','Easy','Cloudflare Enterprise Bot Management subscription.','(http.host eq "www.example.com" and starts_with(http.request.uri.path, "/login") and http.request.method in {"POST"} and any(cf.bot_management.detection_ids[*] in {201326592}))','https://developers.cloudflare.com/bots/additional-configurations/detection-ids/','Consider also implementing Turnstile, a CAPTCHA alternative.','2025-04-22 08:24:32','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(35,'Mitigate Disposable Email Signups','Use Cloudflare Fraud Detection features via WAF rules to block, challenge, log, or rate limit signups using known disposable email domains.','Security',14,2,'Recommended','Medium','Easy',NULL,'(http.host eq "www.example.com" and http.request.uri.path eq "/api/user/create" and http.request.method in {"POST"} and cf.fraud_detection.disposable_email)','https://blog.cloudflare.com/cloudflare-fraud-detection/','Cloudflare Fraud Detection is in early access. Contact your account team.','2025-04-22 08:24:32','2026-10-03 23:29:12');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(36,'Mitigate Logins with Leaked Credentials','Use Leaked Credentials Detection via WAF or Rate Limiting rules to challenge or block login attempts using credentials (passwords) known to be leaked (HIBP), or forward this info to the origin server to trigger password resets for specific users.','Security',14,2,'Recommended','High','Easy',NULL,'(cf.waf.credential_check.password_leaked and http.request.uri.path contains "/api/login" and http.request.method in {"POST"})','https://developers.cloudflare.com/waf/detections/leaked-credentials/','Applies to detected authentication events. Create your own custom detection location. cf.waf.credential_check.username_and_password_leaked (Pro or above) matches only leaked username-password pairs and reduces false positives.','2025-04-22 08:24:32','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(37,'Implement Time-Based Rules','Use the `http.request.timestamp.sec` field in WAF rules to apply logic based on specific time periods (e.g., block POSTs during maintenance window).','Security',4,2,'Situational','Low','Easy',NULL,'(http.request.method eq "POST" and http.request.timestamp.sec gt 1712779200 and http.request.timestamp.sec lt 1712782800)','https://developers.cloudflare.com/ruleset-engine/rules-language/fields/reference/http.request.timestamp.sec/','The timestamp is represented in UNIX time and consists of a 10-digit value.','2025-04-22 08:24:32','2026-10-03 23:29:12');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(38,'Mitigate Unauthorized Worker Subrequests','Prevent abuse from other Cloudflare Workers by using the WAF rules to block subrequests originating from unknown Cloudflare Workers.','Security',4,18,'Situational','Medium','Easy',NULL,'not (cf.worker.upstream_zone in {"" "your-zone.com"})','https://developers.cloudflare.com/fundamentals/reference/http-headers/#cf-worker','Review the documentation on `CF-Connecting-IP` HTTP Request Header in Worker subrequests.','2025-04-22 08:24:32','2026-10-03 23:29:12');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(39,'IP-based Rate Limiting for Logins','Protect login endpoints by creating a Rate Limiting rule that tracks and limits login attempts per IP address over a time window.','Security',5,3,'Recommended','High','Easy',NULL,'Characteristics: IP Address. Match `(http.host eq "www.example.com" and http.request.uri.path eq "/login" and http.request.method eq "POST")`. Action: Block or Log.','https://developers.cloudflare.com/waf/rate-limiting-rules/parameters/','Adjust the rate counter based on expected traffic.','2025-04-22 08:24:32','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(40,'Rate Limit Uploads','Prevent excessive uploads by creating a Rate Limiting rule based on IP address or session, targeting POST/PUT/PATCH methods on upload endpoints.','Security',5,3,'Situational','Medium','Easy',NULL,'Characteristics: IP Address. Match `(http.host eq "www.example.com" and http.request.uri.path eq "/upload" and http.request.method in {"POST" "PUT" "PATCH"})`. Action: Block or Throttle.','https://developers.cloudflare.com/waf/rate-limiting-rules/best-practices/','Adjust the rate counter based on expected traffic.','2025-04-22 08:24:32','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(41,'Rate Limit Credential Stuffing','Mitigate credential stuffing by rate limiting login attempts based on session (cookie/header) or IP or other characteristics, potentially with lower thresholds than general login limiting.','Security',5,3,'Recommended','High','Easy',NULL,'Characteristics: IP + Session Cookie/Header. Match `(http.host eq "www.example.com" and http.request.uri.path eq "/login" and http.request.method eq "POST")`. Action: Block or Throttle.','https://developers.cloudflare.com/waf/rate-limiting-rules/best-practices/#protecting-against-credential-stuffing','Requires a Cloudflare Advanced Rate Limiting subscription. Consider also using the increment counter based on 4XX status code coming from your origin server HTTP Response Code, as well as implementing Turnstile, a CAPTCHA alternative.','2025-04-22 08:24:32','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(42,'Rate Limit Logins with Leaked Passwords','Create a Rate Limiting rule specifically targeting login attempts (authentication events) detected using leaked passwords (HIBP).','Security',5,3,'Recommended','High','Easy',NULL,'Characteristics: IP or Session Cookie/Header. Match `(http.request.uri.path contains "/login" and cf.waf.credential_check.password_leaked)`.','https://developers.cloudflare.com/waf/detections/leaked-credentials/examples/','Consider also implementing Turnstile, a CAPTCHA alternative.','2025-04-22 08:24:32','2026-10-03 23:29:12');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(43,'Geography-based Rate Limiting','If certain countries generate unexpected amounts of traffic, apply rate limiting based on the IP address or other relevant characteristics.','Security',5,3,'Situational','Low','Easy',NULL,'Characteristics: IP Address. Match `ip.src.country in {"DE" "ES"}`.','https://developers.cloudflare.com/waf/rate-limiting-rules/use-cases/','Adjust the rate counter based on expected traffic.','2025-04-22 08:24:32','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(44,'IPv6 Prefix Rate Limiting','Protect against abuse from entire IPv6 prefixes by rate limiting using the `cidr6()` function in custom characteristics.','Security',5,3,'Situational','Medium','Easy',NULL,'Match `(http.host eq "www.example.com" and http.request.uri.path eq "/login" and http.request.method eq "POST")`. Custom Characteristic: `cidr6(ip.src, 48)` (adjust prefix length as needed).','https://developers.cloudflare.com/ruleset-engine/rules-language/functions/#cidr6','Requires a Cloudflare Advanced Rate Limiting subscription. Adjust the rate counter based on expected traffic.','2025-04-22 08:24:32','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(45,'Client Certificate Rate Limiting (mTLS)','Prevent abuse of compromised mTLS certificates or devices by rate limiting requests based on the client certificate fingerprint.','Security',5,10,'Situational','Medium','Easy',NULL,'`(http.host in {"mtls.example.com" "mtls2.example.com"} and cf.tls_client_auth.cert_verified)`. Header value Of Characteristic: `Cf-Client-Cert-Sha256` (SHA256 fingerprint of the certificate).','https://developers.cloudflare.com/ruleset-engine/rules-language/fields/reference/cf.tls_client_auth.cert_fingerprint_sha256/','Implement mTLS best practices. Other mTLS specific fields are also available.','2025-04-22 08:24:32','2026-10-03 23:29:12');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(46,'JavaScript Detection (JSD) Rate Limiting','Rate limit based on repeated failures of JavaScript Detection (JSD) challenges.','Security',5,4,'Situational','Medium','Easy',NULL,'`not cf.bot_management.js_detection.passed`. Characteristic: IP Address. Increment Counter: `(any(http.response.headers["content-type"][*] contains "text/html"))`.','https://developers.cloudflare.com/ruleset-engine/rules-language/fields/reference/cf.bot_management.js_detection.passed/','Requires Cloudflare Enterprise Bot Management subscription. JSD only injects on HTML responses and cannot run on the first request. Consider also implementing Turnstile, a CAPTCHA alternative.','2025-04-22 08:24:32','2026-10-03 23:29:12');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(47,'Implement Turnstile on Forms','Use Cloudflare Turnstile (managed mode recommended) on login, signup, or other forms to distinguish humans from bots without complex CAPTCHAs. Turnstile can also be used with WebViews on mobile devices.','Security',6,8,'Recommended','High','Medium',NULL,'Requires client-side integration and server-side validation using Siteverify API.','https://developers.cloudflare.com/turnstile/get-started/client-side-rendering/',replace('Integrate Turnstile with the WAF and Enterprise Bot Management by enabling the Pre-Clearance Cookie. While Turnstile can be run in invisible mode, it is recommended to use managed mode for login and signup forms to provide users with a clear indication that an action is taking place. Additionally, the Turnstile Siteverify API should be triggered when the user clicks the button, initiating the POST request.\n\n','\n',char(10)),'2025-04-22 08:24:32','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(48,'Monitor Client-side Scripts with Client-side Security','Use Client-side security (formerly Page Shield) to monitor the scripts, connections, and cookies loaded by your pages and get alerted to changes or malicious resources.','Security',13,7,'Recommended','High','Easy','Proxied DNS Records','Enable Client-side security monitoring and configure alerts in Notifications.','https://developers.cloudflare.com/client-side-security/','Script monitoring is available on all plans; connection and cookie monitoring and alerts require Business or above. Malicious script detection and content security rules (positive security model, PCI DSS v4.0 requirement 6.4.3) require Client-Side Security Advanced (formerly the Page Shield add-on).','2025-04-22 08:24:32','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(49,'Use Advanced Certificate Manager (ACM)','Prefer ACM over Universal SSL for more control over certificates, hostnames, and settings.','Security',2,15,'Recommended','Medium','Easy',NULL,NULL,'https://developers.cloudflare.com/ssl/edge-certificates/advanced-certificate-manager/','Review the different SSL and TLS settings, as well as customization requirements. Those seeking PCI compliance and granular customization over cipher suites should review the developer documentations, as well as the features TLS 1.3, Minimum TLS Version (TLS 1.2 is the recommended option here), Automatic HTTPS Rewrites, Always Use HTTPS (or preferably disable HTTP plaintext altogether).','2025-04-22 08:24:32','2026-10-03 23:29:12');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(50,'Disable Universal SSL (and use ACM or Custom Certificates instead)','If using ACM or Custom Certificates, disable the Universal SSL certificate for the Zone.','Security',2,5,'Situational','Low','Easy',NULL,NULL,'https://developers.cloudflare.com/ssl/edge-certificates/universal-ssl/','Verify that there is always a valid and active Edge Certificate for your hostnames.','2025-04-22 08:24:32','2026-10-03 23:29:12');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(51,'Set Minimum TLS Version to 1.2','Configure Cloudflare to only allow TLS 1.2 or higher connections for improved security.','Security',2,5,'Recommended','High','Easy',NULL,NULL,'https://developers.cloudflare.com/ssl/edge-certificates/additional-options/minimum-tls/','Enable TLS 1.3. Recommended option for compliance and security.','2025-04-22 08:24:32','2026-10-03 23:29:12');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(52,'Enable Always Use HTTPS','Force all visitor connections to use HTTPS.','Security',2,5,'Mandatory','High','Easy',NULL,NULL,'https://developers.cloudflare.com/ssl/edge-certificates/additional-options/always-use-https/','Consider also enabling HSTS as well. Preferably disable plaintext HTTP entirely.','2025-04-22 08:24:32','2026-10-03 23:29:12');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(53,'Enable Automatic HTTPS Rewrites','Allow Cloudflare to automatically rewrite HTTP links to HTTPS in HTML source code.','Security',2,5,'Recommended','Low','Easy',NULL,NULL,'https://developers.cloudflare.com/ssl/edge-certificates/additional-options/automatic-https-rewrites/','Helps prevent mixed content warnings. Review your application source code.','2025-04-22 08:24:32','2026-10-03 23:29:12');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(54,'Enable HTTP/2 and HTTP/3','Enable modern HTTP protocols (HTTP/2, HTTP/3 QUIC) for performance and security improvements.','Performance',8,5,'Recommended','Medium','Easy',NULL,NULL,'https://developers.cloudflare.com/speed/optimization/protocol/http3/','Review the Speed Optimization features.','2025-04-22 08:24:32','2025-04-22 08:24:32');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(55,'Enable HTTP/2 to Origin','Allow Cloudflare to use HTTP/2 when connecting to your origin servers if supported.','Performance',8,5,'Recommended','Medium','Easy','Origin server also needs to support HTTP/2 protocol',NULL,'https://developers.cloudflare.com/speed/optimization/protocol/http2-to-origin/','Requires origin server support for HTTP/2. Adjust the connection multiplexing (request pooling).','2025-04-22 08:24:32','2025-04-22 08:24:32');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(56,'Use Logpush for Comprehensive Logs','Configure Logpush to send detailed Firewall events, HTTP request, or other logs to a storage service (R2, S3) or SIEM.','Security',11,11,'Recommended','Medium','Easy',NULL,NULL,'https://developers.cloudflare.com/logs/logpush/','Logpush is strongly recommended for long-term storage and non-sampled logs. Since Birthday Week 2026 it is available on all plans (pay-as-you-go), including Logpush Transformers to filter, redact, and reformat logs with SQL before delivery.','2025-04-22 08:24:32','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(57,'Set Up Notifications','Configure Cloudflare Notifications - email or webhook alerts - for relevant events (security events, certificate expiry, DDoS attacks, and more).','Security',11,20,'Recommended','Medium','Easy',NULL,NULL,'https://developers.cloudflare.com/notifications/','Review available Notifications and configure them based on your needs. Consider using the Cloudflare API or Terraform for automation.','2025-04-22 08:24:32','2025-04-22 08:24:32');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(58,'Use Terraform for Infrastructure as Code (IaC)','Manage Cloudflare configurations using the Cloudflare Terraform Provider for automation, version control, and consistency.','General',12,12,'Recommended','High','Medium','Knowledge of Terraform, version control systems like Git',NULL,'https://developers.cloudflare.com/terraform/',NULL,'2025-04-22 08:24:32','2025-04-22 08:24:32');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(59,'Use Cloudflare API or SDKs for Automation','Leverage the Cloudflare API or official SDKs for custom automation scripts and integrations.','General',12,13,'Recommended','Medium','Medium','Prior knowledge in SDKs or programming is recommended',NULL,'https://developers.cloudflare.com/fundamentals/api/reference/sdks/',NULL,'2025-04-22 08:24:32','2025-04-22 08:24:32');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(60,'Follow Principle of Least Privilege for Users and Tokens','Assign users (or Groups) and API Tokens only the minimum required permissions using specific Roles and scoped tokens. Opt for System for Cross Domain Identity Management (SCIM) User Groups to centralize and simplify your user and group management at scale by syncing memberships directly with your upstream identity provider (IdP).','Security',12,13,'Mandatory','Medium','Medium',NULL,NULL,'https://developers.cloudflare.com/fundamentals/manage-members/','Use Roles for Dashboard UI access and configure API Token permissions separately. Leverage Account Owned Tokens. Customers can also configure Single-Sign-On (SSO) for the Cloudflare Dashboard.','2025-04-22 08:24:32','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(61,'Enforce Multi-Factor Authentication (MFA)','Require MFA for all users accessing the Cloudflare dashboard.','Security',12,25,'Mandatory','High','Easy','Configure either a TOTP mobile app or a security key to enable 2FA on your account',NULL,'https://developers.cloudflare.com/fundamentals/user-profiles/2fa/','MFA is often a compliance requirement. Customers can also configure Single-Sign-On (SSO) for the Cloudflare Dashboard.','2025-04-22 08:24:32','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(62,'Integrate Single Sign-On (SSO)','If applicable, integrate your identity provider (IdP) with Cloudflare for SSO dashboard access.','Security',12,25,'Recommended','High','Complex','Requires a valid Identity Provider (IdP)',NULL,'https://developers.cloudflare.com/fundamentals/manage-members/dashboard-sso/','Review the Cloudflare SSO documentation for best practices, especially backups (break-glass).','2025-04-22 08:24:32','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(63,'Regularly Review Audit Logs','Periodically review Cloudflare Audit Logs to monitor configuration changes and detect suspicious activity.','Security',11,25,'Recommended','Medium','Easy',NULL,NULL,'https://developers.cloudflare.com/fundamentals/account/account-security/review-audit-logs/',NULL,'2025-04-22 08:24:32','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(65,'Use Authenticated Origin Pulls (mTLS)','Configure mTLS between Cloudflare edge and your origin server to ensure requests are genuinely from your Cloudflare account.','Security',7,10,'Recommended','High','Complex','Access to origin server configuration, valid SSL/TLS certificate',NULL,'https://developers.cloudflare.com/ssl/origin-configuration/authenticated-origin-pull/','Review the Cloudflare documentation and follow the best practices.','2025-04-22 08:24:32','2025-04-22 08:24:32');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(66,'Rotate Origin IPs After Onboarding','After migrating to Cloudflare and proxying records, change your origin server IP addresses.','Security',7,25,'Recommended','High','Medium','Access to infrastructure management, DNS control',NULL,'https://developers.cloudflare.com/fundamentals/security/protect-your-origin-server/','Review the Cloudflare documentation and follow the best practices.','2025-04-22 08:24:32','2025-04-22 08:24:32');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(67,'Use Transform Rules for Security Headers','Leverage Managed Transforms or create custom Transform Rules to add or modify security response headers.','Security',7,19,'Recommended','Medium','Medium','Understanding of HTTP security headers',NULL,'https://developers.cloudflare.com/rules/transform/managed-transforms/reference/','Use Cloudflare Snippets for more customizable HTTP header modifications or other custom logics.','2025-04-22 08:24:32','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(68,'Implement API Schema Validation','Use API Shield to upload your API schema (OpenAPI) and enforce validation on incoming requests.','Security',9,6,'Recommended','High','Complex','Valid OpenAPI schema document, API Shield subscription',NULL,'https://developers.cloudflare.com/api-shield/security/schema-validation/','The main goal should be to implement a positive security model for your APIs.','2025-04-22 08:24:32','2025-04-22 08:24:32');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(69,'Use API Shield Sequence Mitigation','Define expected sequences of API calls and use Cloudflare API Shield Sequence Mitigation to detect and block out-of-order requests.','Security',9,6,'Recommended','High','Complex',NULL,NULL,'https://developers.cloudflare.com/api-shield/security/sequence-mitigation/','Review the Cloudflare documentation.','2025-04-22 08:24:32','2025-04-22 08:24:32');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(70,'Configure SPF, DMARC, DKIM DNS records','These records help prevent spoofing, phishing, and unauthorized use of your domain by authenticating outgoing emails and instructing mail servers on how to handle suspicious messages.','Security',1,1,'Recommended','Medium','Easy','Cloudflare is the Authoritative DNS provider',NULL,'https://developers.cloudflare.com/dmarc-management/',NULL,'2025-06-14 21:03:01','2025-06-14 21:03:01');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(71,'Mitigating Pretend-Browsers with JavaScript Detections','In scenarios where the BotScore alone may not reliably differentiate between likely human and bots, you can enhance detection by enabling and enforcing JavaScript Detections (JSD).','Security',4,4,'Recommended','High','Medium','Cloudflare needs at least one HTML request before injecting JSD.','(http.user_agent matches r"^Mozilla/5\.0.+(Chrome|Safari|Firefox)" and not cf.bot_management.js_detection.passed and not cf.bot_management.verified_bot)','https://developers.cloudflare.com/cloudflare-challenges/challenge-types/javascript-detections/#enforcing-execution-of-javascript-detections',NULL,'2025-04-23 21:30:37','2025-06-03 08:22:37');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(72,'Cookie-based Rate Limiting','In order to limit the amount of times a cookie can be used, one can rate limit by its characteristics. For example, rate limit session cookies or limit the amount of times a single cf_clearance cookie can be used.','Security',5,3,'Recommended','High','Medium','Requires Cloudflare Advanced Rate Limiting subscription.','Characteristics: Cookie value of "cf_clearance"','https://developers.cloudflare.com/cloudflare-challenges/challenge-types/challenge-pages/challenge-passage/','When a visitor successfully solves a Managed Challenge, Cloudflare sets a cf_clearance cookie in their browser. This cookie specifies the duration your website is accessible to that visitor, before presenting again a Challenge.','2025-04-23 21:52:02','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(73,'Replace insecure JavaScript Libraries','Automatically rewrites URLs to external JavaScript libraries to point to Cloudflare-hosted libraries instead, i.e. polyfill.','Security',13,2,'Recommended','Medium','Easy','Proxied DNS Records',NULL,'https://developers.cloudflare.com/waf/tools/replace-insecure-js-libraries/',NULL,'2025-04-24 12:27:52','2025-06-03 08:10:52');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(74,'Block HTTP plaintext requests','Enforce not accepting requests in plaintext / unencrypted HTTP requests with a WAF Custom Rule to block any non-HTTPS (not using SSL/TLS) requests.','Security',4,2,'Recommended','High','Easy',NULL,'(not ssl)','https://blog.cloudflare.com/https-only-for-cloudflare-apis-shutting-the-door-on-cleartext-traffic/','It is recommended to also enable the Always Use HTTPS feature with this.','2025-04-24 13:22:29','2025-04-24 13:22:29');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(75,'Return branded Custom Errors as response','Show personalized branded custom content when security challenges or HTTP errors occur from your origin or Cloudflare.','General',12,19,'Optional','Medium','Medium',NULL,NULL,'https://developers.cloudflare.com/rules/custom-errors/','Only available for paid plans.','2025-04-25 21:50:13','2025-04-25 21:50:13');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(76,'Protect against HTTP DDoS botnets','~72% of HTTP DDoS attacks were mitigated by Cloudflare’s botnet-categorized HTTP DDoS Managed rules. It is therefore recommended that Cloudflare customers ensure these rules are enabled with their default settings.','Security',16,21,'Mandatory','High','Easy','Proxied DNS Records',NULL,'https://developers.cloudflare.com/ddos-protection/managed-rulesets/http/rule-categories/','','2025-06-03 06:08:16','2025-06-03 06:08:16');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(77,'Protection against common user-agents seen in HTTP DDoS attacks','Cloudflare has identified the most common user-agents in HTTP DDoS attacks. Cloudflare customers that do not expect traffic from these user-agents are advised to consider rate limiting, challenging, or throttling traffic from these user-agents, perhaps with additional conditions such as source country and path as applicable per Internet property.','Security',16,21,'Situational','High','Easy','Proxied DNS Records','(http.user_agent in {"HITV_ST_PLATFORM Mozilla/5.0 (X11; Ubuntu; Linux x86_64; rv:123.0) Gecko/20100101 Firefox/123.0", "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/119.0.0.0 Safari/537.36", "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/118.0.0.0 Safari/537.36", "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36", "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/121.0.0.0 Safari/537.36", "hackney/1.20.1 Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/117.0.0.0 Safari/537.36", "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/123.0.0.0 Safari/537.36 hackney/1.18.1 uTorrent", "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36", "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/125.0.0.0 Safari/537.36", "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0.0.0 Safari/537.36 fasthttp"})','https://developers.cloudflare.com/ddos-protection/best-practices/proactive-defense/',NULL,'2025-06-03 06:13:35','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(78,'Protection against common HTTP methods seen in HTTP DDoS attacks',replace('GET and POST dominate HTTP traffic and DDoS targets, but lesser-used methods like DELETE are disproportionately abused. Mitigation recommendations include rate-limiting, throttling, or blocking, tailored by factors like source or path.\n\n\n','\n',char(10)),'Security',16,21,'Situational','Medium','Easy','Proxied DNS Records','(http.request.method in {"DELETE" "HEAD" "PATCH"})','https://developers.cloudflare.com/ruleset-engine/rules-language/fields/reference/http.request.method/','Since different websites or endpoints may anticipate specific methods, employing API Shield Schema Validation for API traffic or restricting unexpected methods can significantly enhance a website’s security posture.','2025-06-03 06:28:41','2025-06-03 06:28:41');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(79,'Protecting paths most attacked by HTTP DDoS attacks','Over 96% of traffic towards “/pages/“ and “/wp-login.php/” path was part of HTTP DDoS attacks. Not all of these paths necessarily apply to all HTTP Internet properties, but customers are advised to protect the paths that are applicable to them by rate-limiting, challenging, throttling or blocking requests towards those paths, perhaps with additional conditions such as source country and path as applicable per Internet property.','Security',16,21,'Recommended','Medium','Easy','Proxied DNS Records','(http.request.uri.path ends_with "/wp-login.php/[0-9]+")','https://developers.cloudflare.com/ruleset-engine/rules-language/fields/reference/http.request.uri.path/','Depending on your application, change the path.','2025-06-03 06:34:10','2025-06-03 06:34:10');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(80,'Protection against L3/4 DDoS attacks from high-risk locations','Certain Cloudflare data centers have been observed to ingest a higher amount of L3/4 DDoS attack traffic. Cloudflare customers not expecting traffic from these sources are advised to block traffic from those sources. A less aggressive approach could be rate-limiting traffic from these sources along with additional conditions based on individual relevant fields (e.g. protocol, destination IP, ports, etc).','Security',16,21,'Optional','Medium','Easy',NULL,'(ip.src.country in {"AL" "AZ" "CO" "CD" "DJ" "DO" "EC" "GT" "HN" "MD" "NP" "MK"})','https://radar.cloudflare.com/security/network-layer','Periodically review Cloudflare''s Quarterly DDoS Report to adapt the list of relevant countries involved in DDoS attacks.','2025-06-03 06:38:49','2025-06-03 06:38:49');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(81,'Protection against common and emerging L3/4 DDoS attack vectors','Magic Transit is a network security and performance solution that offers L3/L4 DDoS protection, traffic acceleration, and more for on-premise, cloud-hosted, and hybrid networks.','Security',16,21,'Situational','High','Complex','Own an IP Prefix for BGP announcement via Cloudflare Magic Transit.',NULL,'https://developers.cloudflare.com/ddos-protection/about/attack-coverage/','Review the Cloudflare Magic Transit prerequisites.','2025-06-03 06:42:58','2026-10-03 20:17:50');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(82,'Apex Proxying for Cloudflare for SaaS customers','SaaS providers delivering per-tenant traffic from branded IPs, preserving IP reputation, simplifying Firewall allowlisting, and more advantages, are recommended to opt for BYOIP, or alternatively, Static IPs.','General',17,22,'Situational','High','Medium','Enterprise Plan Paid Add-On',NULL,'https://developers.cloudflare.com/cloudflare-for-platforms/cloudflare-for-saas/start/advanced-settings/apex-proxying/','Apex Proxying requires an A DNS Record, and therefore an IP address. This can be achieved by purchasing a Static IP from Cloudflare, or onboarding BYOIP, which offers more flexibility and additional advantages. In some cases however, some Authoritative DNS Providers allow CNAME Flattening.','2025-06-03 06:54:26','2025-06-03 06:54:26');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(83,'Expose Public Hostnames via Cloudflare Tunnel','Use Cloudflare Tunnel to securely expose specific applications from your origin server while blocking all other inbound traffic, effectively shielding your server from potential threats.','Security',7,1,'Situational','Medium','Medium','Ability to install the Cloudflare Tunnel on the origin server',NULL,'https://developers.cloudflare.com/cloudflare-one/networks/connectors/cloudflare-tunnel/','This is an excellent introduction to Cloudflare’s Zero Trust offering, designed to protect employees, internal networks, and more.','2025-06-13 08:48:40','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(84,'Enable Argo Smart Routing','Argo Smart Routing avoids network congestion by dynamically choosing the fastest path, improving speed and reliability for users far from your origin.','Performance',8,23,'Situational','Medium','Easy','As the distance between visitors and the origin server increases, Argo Smart Routing becomes more effective at optimizing the path from Cloudflare’s edge (PoP) to the origin.',NULL,'https://developers.cloudflare.com/argo-smart-routing/',NULL,'2025-06-13 09:04:48','2025-06-13 09:04:48');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(85,'Configure Tiered Caching','CDN Tiered Cache improves cache hit ratios and reduces origin load by routing requests through a hierarchy of Cloudflare data centers, limiting origin fetches.','Performance',8,24,'Situational','High','Medium',NULL,NULL,'https://developers.cloudflare.com/cache/how-to/tiered-cache/','Determining when to use CDN Tiered Caching versus routing requests directly to Cloudflare Workers requires careful consideration of performance trade-offs. For more customization, consider using Cloudflare Snippets or Workers.','2025-06-14 21:19:01','2025-06-14 21:19:01');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(86,'Gain visibility into third-party Workers requests','Add a header when a Workers Subrequest comes from another zone with Transform Rules.','Security',4,18,'Situational','Medium','Easy',NULL,'(cf.worker.upstream_zone != "" and cf.worker.upstream_zone != "myappexample.com")','https://developers.cloudflare.com/changelog/post/2025-06-09-transform-rule-subrequest-matching/',NULL,'2025-06-23 13:49:05','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(87,'Avoiding Managed Challenge for APIs','Managed Challenge isn''t suitable for API endpoints (AJAX/XHR requests) due to browser CORS restrictions and lack of interactive challenge solving. Instead, detect a Challenge Page response or use Turnstile on key frontend pages to issue a Clearance Cookie (cf_clearance), allowing smooth API access without blocking or user friction.','Security',4,2,'Recommended','High','Medium','API (AJAX/XHR requests)',NULL,'https://developers.cloudflare.com/cloudflare-challenges/challenge-types/challenge-pages/detect-response/','Review the Challenges FAQ section.','2025-07-29 10:58:52','2025-07-29 10:58:52');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(88,'Protect Native Mobile Applications (iOS and Android)','Cloudflare Bot Management Mobile SDK secures backend and third-party APIs from abuse by verifying mobile app and device integrity, issuing signed JWTs for authentication, and enabling precise rate limiting with Cloudflare API Shield (API security) integration.','Security',6,4,'Situational','High','Complex','Mobile SDK implementation on the native mobile app',NULL,NULL,'Requires Enterprise Bot Management, and API Shield is recommended, though one could implement JWT Validation on their origin server. API Shield and Advanced Rate Limiting are required for JWT claim based rate limiting.','2025-08-12 09:54:00','2026-10-03 20:17:50');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(89,'Exclude Challenge Pages (cdn-cgi endpoint)','Cloudflare Challenge Pages are isolated for security. Custom headers and policies are blocked, and Transform Rules altering response headers must exclude Challenge paths to avoid failures.','Security',4,2,'Recommended','High','Medium','Content Security Policy (CSP) or Referer-Policy using `<meta>` tags or Transform Rules','not (starts_with(http.request.uri.path, "/cdn-cgi/challenge-platform/") or cf.response.error_type in "managed_challenge" "iuam" "legacy_challenge" "country_challenge")','https://developers.cloudflare.com/cloudflare-challenges/challenge-types/challenge-pages/additional-configuration/','Review the /cdn-cgi/ endpoint developer documentation.','2025-10-07 18:17:52','2025-10-07 18:17:52');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(90,'Block Access to Sensitive Files and Paths','Block requests for configuration files, version control metadata, backups, and debugging endpoints that should never be publicly reachable.','Security',4,2,'Recommended','High','Easy',NULL,'((http.request.uri.path contains "/.git" or http.request.uri.path contains "/.svn" or http.request.uri.path contains "/.env" or http.request.uri.path contains "/.htaccess" or http.request.uri.path contains "/.htpasswd" or http.request.uri.path contains "/.DS_Store" or ends_with(http.request.uri.path, ".sql") or ends_with(http.request.uri.path, ".bak") or ends_with(http.request.uri.path, ".old") or http.request.uri.path in {"/wp-config.php" "/phpinfo.php"}) and not starts_with(http.request.uri.path, "/.well-known/"))','https://developers.cloudflare.com/waf/custom-rules/use-cases/','Keep /.well-known/ reachable (ACME HTTP validation, security.txt). Adjust the list to your stack; the real fix is to not have these files on the origin at all.','2026-10-03 23:31:40','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(91,'Validate Rule Changes with Dry Run','Validate WAF and Rate Limiting rule changes before publishing them by appending dry_run=true to Rulesets API write requests.','General',12,13,'Recommended','Medium','Easy','API token with the same permission as the real change (for example, Zone > WAF > Edit).','curl "https://api.cloudflare.com/client/v4/zones/$ZONE_ID/rulesets/phases/http_request_firewall_custom/entrypoint?dry_run=true" --request PUT --header "Authorization: Bearer $CLOUDFLARE_API_TOKEN" --header "Content-Type: application/json" --data ''{"rules":[{"description":"Dry-run validation example","expression":"(http.request.uri.path ne \"/robots.txt\" and cf.bot_management.verified_bot)","action":"log","enabled":true}]}''','https://developers.cloudflare.com/ruleset-engine/rulesets-api/','A valid request returns 200 with "result": null (nothing is saved); an invalid one returns the same error the real write would. Validation covers expression syntax, field/function availability, actions, phase compatibility, permissions, plan entitlements, and quotas. Ideal for CI pipelines (Terraform, scripts).','2026-10-03 23:31:40','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(92,'Roll Out New Blocking Rules Gradually','Apply a new blocking rule to a small share of clients first with the hash_in_range() function, then increase the share while monitoring Security Events.','General',4,2,'Optional','Medium','Medium','Rule validated with the Log action first.','(hash_in_range(0, 100, ip.src) lt 10 and <your rule condition>)','https://developers.cloudflare.com/ruleset-engine/rules-language/functions/','Seeding with ip.src keeps each client consistently in or out of the rollout; use cf.random_seed to sample individual requests instead. Raise the upper bound (10, 25, 50, 100) as confidence grows. Available on all plans.','2026-10-03 23:31:40','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(93,'Rate Limit OTP, Verification and Password Reset Endpoints','Rate limit failed attempts on one-time password (OTP), email/SMS verification, and password reset endpoints, which are brute-forced like logins but frequently forgotten.','Security',5,3,'Recommended','High','Easy',NULL,'Expression: (http.host eq "www.example.com" and http.request.uri.path in {"/api/otp/validate" "/account/verify" "/password-reset"} and http.request.method eq "POST"). Characteristics: IP. Counting expression: (http.request.uri.path in {"/api/otp/validate" "/account/verify" "/password-reset"} and http.request.method eq "POST" and http.response.code in {401 403}). Rate: 5 requests / 1 minute. Action: Block for 10 minutes.','https://developers.cloudflare.com/waf/rate-limiting-rules/best-practices/#protect-otp-and-verification-endpoints','Counting only failed attempts never affects users submitting a valid code. If the endpoint returns 200 for both valid and invalid codes, drop the response code condition and use a lower request-based threshold.','2026-10-03 23:31:40','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(94,'Rate Limit Clients Generating Errors','Challenge clients that produce a high volume of 403 or 404 responses, which usually indicates scanners, scrapers, or fuzzers enumerating paths.','Security',5,3,'Situational','Medium','Medium',NULL,'Expression: (http.host eq "www.example.com" and not cf.bot_management.verified_bot). Characteristics: IP. Counting expression: (http.host eq "www.example.com" and not cf.bot_management.verified_bot and http.response.code in {403 404}). Rate: more than 20 errors / 1 minute. Action: Managed Challenge.','https://developers.cloudflare.com/waf/rate-limiting-rules/best-practices/#limit-requests-from-bots','Because the counting expression uses a response field, matching requests bypass the cache. On static-heavy hostnames, narrow the rule expression (for example, not starts_with(http.request.uri.path, "/assets/") or not cf.bot_management.static_resource). Single-page applications and sites with many broken links generate legitimate 404s; tune the threshold.','2026-10-03 23:31:40','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(95,'Rate Limit API Clients by Key or Token','For authenticated APIs, rate limit per API key, bearer token, or session instead of per IP, since one key may be used from many IPs and many keys from one IP.','Security',5,3,'Recommended','High','Medium','Advanced Rate Limiting (header-based counting characteristics).','Expression: (http.host eq "api.example.com" and starts_with(http.request.uri.path, "/v1/") and len(http.request.headers["x-api-key"]) gt 0). Characteristics: Header value of x-api-key (or authorization).','https://developers.cloudflare.com/waf/rate-limiting-rules/best-practices/#protecting-rest-apis','Header names must be lowercase when used via the API. Requests without the header fall into their own counter, so handle unauthenticated requests with a separate IP-based rule. The identifier can also be a cookie, query parameter, JSON body field, or JWT claim. Use API Discovery or the request rate analysis to choose thresholds.','2026-10-03 23:31:40','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(96,'Rate Limit Content Scraping per Operation','Limit how often a client can perform a specific operation (for example, price lookups) to stop scraping by bots that evade other detections.','Security',5,3,'Situational','Medium','Easy',NULL,'Rule 1: (http.request.uri.path eq "/merchant" and http.request.uri.query contains "action=lookup_price"), Characteristics: IP, Rate: 10 requests / 2 minutes, Action: Managed Challenge. Rule 2: same expression, Rate: 20 requests / 5 minutes, Action: Block.','https://developers.cloudflare.com/waf/rate-limiting-rules/best-practices/#prevent-content-scraping-via-query-string','A lenient challenge rule followed by a stricter block rule reduces false positives for persistent but legitimate users. The same pattern applies to operations identified in the request body.','2026-10-03 23:31:40','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(97,'Rate Limit GraphQL Operations','GraphQL APIs use a single path and mostly POST requests, so rate limit by operation name in the body (and, with API Shield, by query complexity) instead of by path and method.','Security',9,3,'Situational','Medium','Medium','Advanced Rate Limiting and payload inspection.','Expression: (http.request.uri.path eq "/graphql" and http.request.body.raw contains "createReview"). Characteristics: Cookie (session_id). Rate: 5 requests / 1 hour. Action: Block.','https://developers.cloudflare.com/waf/rate-limiting-rules/best-practices/#protecting-graphql-apis','Also consider limiting the total query complexity per client over time and the complexity of individual queries (GraphQL malicious query protection in API Shield).','2026-10-03 23:31:40','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(98,'Protect LLM Endpoints with AI Security for Apps','Detect and mitigate prompt injection, PII in prompts, and unsafe topics on LLM-powered endpoints (chatbots, assistants) with AI Security for Apps (formerly Firewall for AI).','Security',18,26,'Situational','High','Medium','LLM endpoints labeled cf-llm in Web Assets; JSON request bodies.','(cf.llm.prompt.injection_score lt 20) or (cf.llm.prompt.pii_detected)','https://developers.cloudflare.com/waf/detections/ai-security-for-apps/','Start with Log and review Security Analytics filtered by the cf-llm label. Combine signals to reduce false positives, for example (cf.llm.prompt.injection_score lt 25 and cf.bot_management.score lt 10). LLM endpoint discovery is available on all plans; detection fields require an Enterprise add-on.','2026-10-03 23:31:40','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(99,'Scan Uploads for Malicious Content','Use WAF content scanning to detect malware in uploaded files and block requests that contain malicious content objects.','Security',4,29,'Situational','High','Easy','Malicious uploads detection enabled (Enterprise add-on).','(cf.waf.content_scan.has_malicious_obj)','https://developers.cloudflare.com/waf/detections/malicious-uploads/','Also log requests where scanning failed or the body was truncated (cf.waf.content_scan.has_failed, cf.waf.content_scan.truncated) to spot gaps, and restrict allowed file types with cf.waf.content_scan.obj_types.','2026-10-03 23:31:40','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(100,'Use Threat Intelligence in WAF Rules','Match client IPs against Cloudforce One threat intelligence (IPs involved in DDoS or WAF attack activity in the past seven days) and combine it with other signals.','Security',4,28,'Situational','Medium','Easy','Active Cloudforce One subscription.','(any(cf.intel.ip.datasets[*] == "waf") and cf.waf.score lt 20)','https://developers.cloudflare.com/waf/detections/threat-intelligence/','IP addresses are often shared (NAT, proxies, cloud providers): test with Log first and combine with Attack Score or bot signals before blocking. Since Birthday Week 2026, the Threat Events Platform and Threat Signals are free for every account for investigations.','2026-10-03 23:31:40','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(101,'Control AI Crawlers by Purpose (Search, Agent, Training)','Use AI Crawl Control to decide separately whether AI search crawlers, AI agents, and AI training crawlers may access your content, and monitor robots.txt compliance.','General',6,27,'Recommended','Medium','Easy',NULL,'AI Crawl Control: set Search, Agent, and Training to allow, block on all pages, or block only on pages with ads. Optionally block individual crawlers and enforce robots.txt.','https://developers.cloudflare.com/ai-crawl-control/','Available on all plans, including Free. robots.txt and Content Signals only express preferences; use block actions to enforce them. Agents that sign requests with Web Bot Auth can be identified with cf.bot_management.signed_agent.','2026-10-03 23:31:40','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(102,'Enable Post-Quantum Encryption to the Origin','Make sure the origin server supports the hybrid post-quantum key agreement X25519MLKEM768 over TLS 1.3, so the Cloudflare-to-origin connection is protected against harvest-now, decrypt-later attacks.','Security',2,5,'Recommended','Medium','Medium','TLS 1.3 on the origin server.','bssl client -connect <YOUR_ORIGIN>:443 -curves X25519MLKEM768','https://developers.cloudflare.com/ssl/post-quantum-cryptography/pqc-to-origin/','Automatic key exchange (on by default) prefers X25519MLKEM768 whenever the origin supports it; only about 15% of origins did as of Birthday Week 2026. Verify that the handshake reports X25519MLKEM768. Monitor visitor-side adoption in HTTP Traffic Analytics or with the ClientTLSKeyExchangeGroup Logpush field.','2026-10-03 23:31:40','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(103,'Enforce a Positive Security Model with Application Profiles','Let Cloudflare learn the expected structure of requests to your web application (data types, ranges, formats) and act on non-conforming requests with Security Rules.','Security',9,6,'Situational','High','Medium','Closed beta for invited Enterprise customers; customers with API Security already have access.','Onboard the application in Web Assets, select operations to profile, review conforming and non-conforming traffic in observation mode, then create Security Rules for selected paths, operations, or fields.','https://blog.cloudflare.com/application-profiles/','An operation needs at least 1,000 requests with a 2xx response in the previous seven days to learn fields (10,000 to learn data boundaries). Profiles relearn weekly; pin a learned schema by uploading it to Schema Validation.','2026-10-03 23:31:40','2026-10-03 23:31:40');
